/* eslint-disable */
import gql from 'graphql-tag';
import * as Apollo from '@apollo/client';
export type Maybe<T> = T;
export type InputMaybe<T> = T;
export type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]?: Maybe<T[SubKey]> };
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]: Maybe<T[SubKey]> };
export type MakeEmpty<T extends { [key: string]: unknown }, K extends keyof T> = { [_ in K]?: never };
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
const defaultOptions = {} as const;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  /** A Byte scalar type represents a signed 8-bit numeric non-fractional value */
  Byte: { input: any; output: any; }
  /** A scalar which represents java.lang.Character */
  Char: { input: any; output: any; }
  /** The Common_Country is an ISO-3166-1 country. */
  Common_Country: { input: any; output: any; }
  /** The Common_Currency is an ISO-4217 currency. */
  Common_Currency: { input: any; output: any; }
  /** An ISO-8601 encoded date string (YYYY-MM-DD), e.g. '2021-08-26' */
  Date: { input: any; output: any; }
  /** An ISO-8601 encoded UTC date string with millisecond precision (YYYY-MM-DDThh:mm:ss.mmmZ), e.g. '2021-08-26T23:18:50.870Z' */
  DateTime: { input: any; output: any; }
  /**
   * A scalar which represents fixed point/precision decimal numbers
   * JavaScript (TypeScript), Python equivalent: Decimal
   * We will decide later on how these values are represented on the wire
   */
  Decimal: { input: any; output: any; }
  /** Error specific (not for general use) scalar that could accept both String and Int */
  ErrorPathElement: { input: any; output: any; }
  /** account purpose scalar that accepts String values */
  Identity_AccountPurpose: { input: any; output: any; }
  /**
   * Identity_ContactPurpose scalar is not generally available. Continue to use purpose enum.
   * contactPurpose scalar that accepts String values like: BILLING, GENERAL, LEGAL, ORDER, OTHER, SHIPPING, SUPPORT, UNKNOWN
   */
  Identity_ContactPurpose: { input: any; output: any; }
  /**
   * Identity_ContactUsage scalar - Use this instead of the deprecated ContactUsage enum.
   * contactUsage scalar that accepts String values like: ALTERNATE, BUSINESS, HOME, OTHER, PUBLIC, INDIVIDUAL, UNKNOWN
   */
  Identity_ContactUsage: { input: any; output: any; }
  /**
   * "
   * verification method scalar that accepts String values like: CARE, THIRD_PARTY, UNKNOWN, USER, KYC, KYB
   */
  Identity_VerificationMethod: { input: any; output: any; }
  /**
   * A synonym for the Object scalar, it will accept any object as a scalar value
   *
   * One of the design goals of GraphQL, is that the type system describes the shape of the data returned.
   *
   * The Object / JSON scalars work against this some what because they can return compound values outside the type system. As such they should be used sparingly. In general your should aim to describe the data via the GraphQL type system where you can and only resort to the Object / JSON scalars in very rare circumstances.
   *
   * An example might be an extensible GraphQL system where systems can input custom metadata objects that cant be known at schema type design time.
   */
  JSON: { input: any; output: any; }
  /** The Locale scalar handles IETF BCP 47 language tags */
  Locale: { input: any; output: any; }
  /** This is used until we can support DateTime for timestamp */
  Long: { input: any; output: any; }
  /** An Int scalar that represents a non-negative 32-bit numeric non-fractional value. */
  NonNegativeInt: { input: any; output: any; }
  /** An object scalar that accepts any object as a scalar value. */
  Object: { input: any; output: any; }
  /** An Float scalar type represents positive double-precision finite values as specified by IEEE 754 */
  PositiveFloat: { input: any; output: any; }
  /** An Int scalar that represents a positive 32-bit numeric non-fractional value. */
  PositiveInt: { input: any; output: any; }
  /** A Long scalar type represents a positive 64-bit numeric non-fractional value */
  PositiveLong: { input: any; output: any; }
  /** A Short scalar type represents a positive 16-bit numeric non-fractional value */
  PositiveShort: { input: any; output: any; }
  /** A Short scalar type represents a signed 16-bit numeric non-fractional value */
  Short: { input: any; output: any; }
  /** An RFC-3339 (ISO-8601) compliant time scalar that accepts string values like 16:39:57-08:00 */
  Time: { input: any; output: any; }
  /** A universally unique identifier scalar that accepts uuid values like 2423f0a0-3b81-4115-a189-18df8b35e8fc */
  UUID: { input: any; output: any; }
  /** An url scalar that accepts string values like https://www.w3.org/Addressing/URL/url-spec.txt */
  Url: { input: any; output: any; }
};

