/** Classification/Importance of the contact type */
export enum Common_Ordinal {
  Other = 'OTHER',
  Primary = 'PRIMARY',
  Secondary = 'SECONDARY',
  Tertiary = 'TERTIARY',
  Unknown = 'UNKNOWN'
}

/**
 * Relay spec complaint PageInfo.  See here for more details:
 * https://relay.dev/graphql/connections.htm
 */
export type Common_PageInfo = {
  __typename?: 'Common_PageInfo';
  /** endCursor is the cursor corresponding to the last node in edges.  It can be null in case of no results. */
  endCursor?: Maybe<Scalars['String']['output']>;
  /** hasNextPage is used to indicate whether more edges exist following the set defined by the clients arguments. */
  hasNextPage: Scalars['Boolean']['output'];
  /** hasPreviousPage is used to indicate whether more edges exist prior to the set defined by the clients arguments. */
  hasPreviousPage: Scalars['Boolean']['output'];
  /** startCursor is the cursor corresponding to the first node in edges.  It can be null in case of no results. */
  startCursor?: Maybe<Scalars['String']['output']>;
};

