export type DataAccess_AdditionalAttribute = {
  __typename?: 'DataAccess_AdditionalAttribute';
  key: Scalars['String']['output'];
  value?: Maybe<Scalars['String']['output']>;
};

export type DataAccess_Address = Common_PostalAddressSimple & {
  __typename?: 'DataAccess_Address';
  active: Scalars['Boolean']['output'];
  address?: Maybe<Scalars['String']['output']>;
  addressId?: Maybe<Scalars['String']['output']>;
  city?: Maybe<Scalars['String']['output']>;
  companyId: Scalars['String']['output'];
  country?: Maybe<Common_CountryCode>;
  /**
   * When creating an address, users are allowed to enter a free text field for the country.
   * This free text is stored in the Ceres DB under the 'country' attribute.
   * When retrieving address information with the DAS service, the free text value is returned under 'countryName'.
   * Additionally, if possible, DAS will also map the value to the corresponding country code in the Common_CountryCode list
   * and return it under 'country'
   */
  countryName?: Maybe<Scalars['String']['output']>;
  formatted?: Maybe<Scalars['String']['output']>;
  freeForm?: Maybe<Scalars['String']['output']>;
  geoLocation?: Maybe<Common_GeoLocation>;
  id: Scalars['ID']['output'];
  meta?: Maybe<DataAccess_Metadata>;
  postalCode?: Maybe<Scalars['String']['output']>;
  /** Address edit-sequence value set by the upstream. When document is updated, upstream increments the value of edit-sequence. */
  sourceEntityVersion?: Maybe<Scalars['Int']['output']>;
  state?: Maybe<Scalars['String']['output']>;
  streetAddressLine1: Scalars['String']['output'];
  streetAddressLine2?: Maybe<Scalars['String']['output']>;
  streetAddressLine3?: Maybe<Scalars['String']['output']>;
};

export type DataAccess_AddressConnection = {
  __typename?: 'DataAccess_AddressConnection';
  edges: Array<DataAccess_AddressEdge>;
  nodes: Array<DataAccess_Address>;
  pageInfo: Common_PageInfo;
  /** total number of Address records matched */
  totalCount: Scalars['Int']['output'];
};

/**
 * Address directory containing references to billing, shipping, and primary addresses.
 * The billing, shipping, and primary fields resolve to full Address entities from the address index.
 */
export type DataAccess_AddressDirectory = {
  __typename?: 'DataAccess_AddressDirectory';
  /** Resolved billing addresses */
  billing: Array<DataAccess_Address>;
  /** IDs of billing addresses */
  billingIds: Array<Scalars['String']['output']>;
  /** Resolved primary addresses */
  primary: Array<DataAccess_Address>;
  /** IDs of primary addresses */
  primaryIds: Array<Scalars['String']['output']>;
  /** Resolved shipping addresses */
  shipping: Array<DataAccess_Address>;
  /** IDs of shipping addresses */
  shippingIds: Array<Scalars['String']['output']>;
};

/**
 * Relay edge containing a address.
 * https://relay.dev/graphql/connections.htm
 */
export type DataAccess_AddressEdge = {
  __typename?: 'DataAccess_AddressEdge';
  cursor: Scalars['String']['output'];
  highlights: Array<Common_Highlight>;
  node: DataAccess_Address;
  /**
   * Address score. A non-negative score indicating how good of a match has been found with a higher number being a better match.
   * Zero indicates that there was no relative ranking attempted because the a deterministic filter across all addresses has been applied instead.
   * The value of this field should used only relatively against other addresses in the connection. You should not use the absolute value of this score.
   * Note: this field is computed internally by using OpenSearch's BM25 algorithm, but you should not need to rely on the relevance algorithm used.
   */
  score: Scalars['Decimal']['output'];
};

/** Address types */
export type DataAccess_AddressFilter = {
  active?: InputMaybe<Common_BooleanFilter>;
  /** filter based on search conditions across the entire address; also influences the scores of the returned addresses */
  addressSearch?: InputMaybe<DataAccess_AddressSearch>;
  and?: InputMaybe<Array<DataAccess_AddressFilter>>;
  city?: InputMaybe<DataAccess_StringFilter>;
  countryName?: InputMaybe<DataAccess_StringFilter>;
  id?: InputMaybe<Common_IdsFilter>;
  or?: InputMaybe<Array<DataAccess_AddressFilter>>;
  postalCode?: InputMaybe<DataAccess_StringFilter>;
  state?: InputMaybe<DataAccess_StringFilter>;
  streetAddressLine1?: InputMaybe<DataAccess_StringFilter>;
};

/**
 * Search an address across multiple fields. At least one field must be non-null, though they may all be empty.
 * An address is included only if at least one of the non-null (including empty) fields contains the 'searchText' (disregarding case)
 */
export type DataAccess_AddressSearch = {
  /** whether to include city in the text search */
  city?: InputMaybe<DataAccess_Search>;
  /** case-insensitive search text to match in address fields */
  searchText?: InputMaybe<Scalars['String']['input']>;
  /** whether to include streetAddressLine1 in the text search */
  streetAddressLine1?: InputMaybe<DataAccess_Search>;
};

export enum DataAccess_AddressType {
  Billing = 'BILLING',
  Primary = 'PRIMARY',
  Shipping = 'SHIPPING',
  ShipFrom = 'SHIP_FROM'
}

export enum DataAccess_AddressesSort {
  /**
   * Sort by the active field of the address.
   * An ascending active search is FALSE first, then TRUE
   */
  ActiveAsc = 'ACTIVE_ASC',
  ActiveDesc = 'ACTIVE_DESC',
  CityAsc = 'CITY_ASC',
  CityDesc = 'CITY_DESC',
  CountryNameAsc = 'COUNTRY_NAME_ASC',
  CountryNameDesc = 'COUNTRY_NAME_DESC',
  PostalCodeAsc = 'POSTAL_CODE_ASC',
  PostalCodeDesc = 'POSTAL_CODE_DESC',
  /**
   * Sort by the edge's score.
   * Note that score for a document can be modified by search terms, search fields, and boosts of the search
   */
  ScoreAsc = 'SCORE_ASC',
  ScoreDesc = 'SCORE_DESC',
  StateAsc = 'STATE_ASC',
  StateDesc = 'STATE_DESC',
  StreetAddressLines_1Asc = 'STREET_ADDRESS_LINES_1_ASC',
  StreetAddressLines_1Desc = 'STREET_ADDRESS_LINES_1_DESC'
}

