/**
 * Relay edge containing a address.
 * https://relay.dev/graphql/connections.htm
 */
export type DataAccess_ForecastEdge = {
  __typename?: 'DataAccess_ForecastEdge';
  cursor: Scalars['String']['output'];
  highlights: Array<Common_Highlight>;
  node: DataAccess_Forecast;
  /**
   * Forecast score. A non-negative score indicating how good of a match has been found with a higher number being a better match.
   * Zero indicates that there was no relative ranking attempted because the a deterministic filter across all addresses has been applied instead.
   * The value of this field should used only relatively against other addresses in the connection. You should not use the absolute value of this score.
   * Note: this field is computed internally by using ElasticSearch's BM25 algorithm, but you should not need to rely on the relevance algorithm used.
   */
  score: Scalars['Decimal']['output'];
};

