export type Internationalization = {
  __typename?: 'Internationalization';
  /** This contains the country code */
  country?: Maybe<Scalars['String']['output']>;
  /** This contains the ISO 8601 date and time format. */
  dateFormat?: Maybe<Scalars['String']['output']>;
  /**
   * This contains the 2 letter language code as per ISO639-2: Language Code
   * @deprecated Language Type is deprecated and is replaced by Locale, which is a representation of region and language preference. This will be removed from schema by end of FY26 Q3, i.e. April 30, 2026.
   */
  language?: Maybe<LanguageType>;
  /** This contains the language and region preference for users. e.g. : en-US */
  locale?: Maybe<Scalars['String']['output']>;
  /** This contains the 3 letter country code (as per ISO 3166 alpha-3 country code) of the country whose number format you want. The number format is derived using the country code. */
  numberFormat?: Maybe<Scalars['String']['output']>;
  /** This contains the region preferences of the user */
  region?: Maybe<Scalars['String']['output']>;
  /** This contains the GMT Sign Hours. Example: GMT+/-{Zone hour values}. Zone hour values is the time difference or offset relative to GMT */
  timeZone?: Maybe<Scalars['String']['output']>;
};

export type InternationalizationInput = {
  country?: InputMaybe<Country>;
  /** This contains the ISO 8601 date and time format. */
  dateFormat?: InputMaybe<Scalars['String']['input']>;
  /** This contains the 2 letter language code as per ISO639-2: Language Code */
  language?: InputMaybe<LanguageType>;
  locale?: InputMaybe<Scalars['String']['input']>;
  /** This contains the 3 letter country code (as per ISO 3166 alpha-3 country code) of the country whose number format you want. The number format is derived using the country code. */
  numberFormat?: InputMaybe<Scalars['String']['input']>;
  region?: InputMaybe<Scalars['String']['input']>;
  /** This contains the GMT Sign Hours. Example: GMT+/-{Zone hour values}. Zone hour values is the time difference or offset relative to GMT */
  timeZone?: InputMaybe<Scalars['String']['input']>;
};

