/**
 * Represents a specific spiltDetails to be used in the accounting. Examples of spiltType in accounting are project, customer, service, class, etc.
 * Not all EmployeeCompensationSplitData in accounting are supported - please see DataType enum for list of supported dat types.
 */
export type Payroll_CompensationSplitDetailV2 = {
  __typename?: 'Payroll_CompensationSplitDetailV2';
  /** The data ID for this split detail */
  dataId: Scalars['ID']['output'];
  /** accounting datatype that is allocated to this compensation. */
  dataType: Payroll_CompensationSplitTypeV2;
  /** The dimension id for this split detail */
  dimensionId?: Maybe<Scalars['String']['output']>;
};

/** List of accounting related datatypes that can be used to allocate calculated compensations against. */
export enum Payroll_CompensationSplitType {
  /** compensations split by class */
  Class = 'CLASS',
  /** compensations split by dimension */
  Dimension = 'DIMENSION',
  /** compensations split by project */
  Project = 'PROJECT',
  /** the unspecified category */
  Unspecified = 'UNSPECIFIED'
}

/** List of accounting related datatypes that can be used to allocate calculated compensations against. */
export enum Payroll_CompensationSplitTypeV2 {
  /** compensations split by class */
  Class = 'CLASS',
  /** compensations split by dimensions */
  Dimension = 'DIMENSION',
  /** compensations split by project */
  Project = 'PROJECT'
}

/** Represents a singular grouping of EmployeeCompensationSplitDetail and the associated hours and/or amount associated with it. */
export type Payroll_CompensationSplitV2 = {
  __typename?: 'Payroll_CompensationSplitV2';
  /** Split amount of MoneyAmount for this single EmployeeCompensationSplit of compensation. */
  amount: Common_MoneyAmount;
  /** Number of hours for this single EmployeeCompensationSplit of compensation. */
  hours?: Maybe<Scalars['Decimal']['output']>;
  /** Compensation split id */
  id: Scalars['ID']['output'];
  /**
   * The list of splitDetails specified here compose a singular EmployeeCompensationSplit. The hours and/or amount associated
   * with this singular EmployeeCompensationSplit are allocated to every single splitDetails in this list of EmployeeCompensationSplitDetail.
   */
  splitDetails: Array<Payroll_CompensationSplitDetailV2>;
  /**
   * Split percentage of the employeeCompensationSplit is the weight of this employeeCompensationSplit within a list of employeeCompensationSplits.
   * The total sum of % across a list of employeeCompensationSplits should not exceed 100. If the total sum of % is below 100, then the remaining % is deemed unallocated.
   */
  splitPercentage?: Maybe<Scalars['Decimal']['output']>;
};

