/**
 * Interface for BusinessTransaction to be inherited by all business transactions across various
 * domains such as Sales, Expenses, Inventory, Accounting.
 */
export type Qb_BusinessTransaction = {
  /** indicates if the entity is active or inactive. inactive will be used for soft deletes. active = 1 inactive = 0 */
  active?: Maybe<Scalars['Boolean']['output']>;
  /** Other ids: external, internal, relative to the current system */
  alternativeIds?: Maybe<Array<Maybe<Qb_AlternateId>>>;
  /** approval info of a transaction */
  approvalInfo?: Maybe<Qb_ApprovalInfo>;
  /** attachments on transaction */
  attachments?: Maybe<Array<Maybe<Qb_AttachmentInfo>>>;
  /** creation status of the transaction */
  creationStatus?: Maybe<Qb_CreationStatus>;
  /** ISO 4217 currency code in which the transaction is performed */
  currencyCode?: Maybe<Common_CurrencyCode>;
  /** selected/set values of custom extensions such as custom fields, tags, dimensions, etc associated with the transaction */
  customExtensions?: Maybe<Array<Maybe<Qb_CustomExtensionValueInfo>>>;
  /** custom fields on transaction */
  customFields?: Maybe<Qb_CustomFieldInfo>;
  /** currency exchange rate as per home currency of the company */
  exchangeRate?: Maybe<Scalars['Decimal']['output']>;
  /** entity references to entities from external applications, both within and outside of Intuit */
  externalReferences?: Maybe<Array<Maybe<Qb_ExternalReference>>>;
  /** Total amount in home currency of the transaction */
  homeTotalAmount?: Maybe<Common_MoneyAmount>;
  /** Globally-unique identifier for a resource. */
  id: Scalars['ID']['output'];
  /** The intuitAccountId field is an Identity 2.0 concept that uses either realmIds (SBSEG) or userIds (CG). */
  intuitAccountId: Scalars['ID']['output'];
  /** linked transactions (Ex. invoice -> payment, invoice -> sales order, payment -> credit memo etc) */
  links?: Maybe<Array<Maybe<Qb_TransactionLink>>>;
  /** Location ID on transaction */
  locationId?: Maybe<Scalars['String']['output']>;
  /** description of the transaction. */
  memo?: Maybe<Scalars['String']['output']>;
  /**
   * Contains meta-data details common to all entities in the system such
   * as who/what/when created and/or modified the entity. All entities are required
   * to support these fields
   */
  meta?: Maybe<Qb_Metadata>;
  /** identifier entered by user. */
  referenceNumber?: Maybe<Scalars['String']['output']>;
  /** tag ids on transaction */
  tags?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
  /** Total amount including any shipping fees, sales tax, and discounts. currency is required */
  totalAmount?: Maybe<Common_MoneyAmount>;
  /** represents the date on which a trade took place between buyer and seller */
  transactionDate?: Maybe<Scalars['Date']['output']>;
  /**
   * version of the entity. Every domain entity needs to have a monotonically incrementing version of each change.
   * This helps downstreams identity out of order events. Example 0, 1, 2 and so on
   */
  version?: Maybe<Scalars['Int']['output']>;
};

