  dataAccessContacts?: Maybe<DataAccess_ContactConnection>;
  /** All the CostGroup entities associated with the company */
  dataAccessCostGroups?: Maybe<DataAccess_CostGroupConnection>;
  /** All the CustomDimensionDefinition entities associated with the company */
  dataAccessCustomDimensionDefinitions?: Maybe<DataAccess_CustomDimensionDefinitionConnection>;
  /** All the CustomDimensionValue entities associated with the company */
  dataAccessCustomDimensionValues?: Maybe<DataAccess_CustomDimensionValueConnection>;
  /** All the CustomFieldDefinition entities associated with the company */
  dataAccessCustomFieldDefinitions?: Maybe<DataAccess_CustomFieldDefinitionConnection>;
  /** All the CustomFieldDefinitionV2 entities associated with the company */
  dataAccessCustomFieldDefinitionsV2?: Maybe<DataAccess_CustomFieldDefinitionV2Connection>;
  /** All the CustomObjectValue entities associated with the company */
  dataAccessCustomObjectValues?: Maybe<DataAccess_CustomObjectValueConnection>;
  dataAccessDepartments?: Maybe<DataAccess_DepartmentConnection>;
  dataAccessForecast?: Maybe<DataAccess_ForecastConnection>;
  /** All the Klass entities associated with the company */
  dataAccessKlasses?: Maybe<DataAccess_KlassConnection>;
  /** All the Lead entities associated with the company */
  dataAccessLeads?: Maybe<DataAccess_LeadConnection>;
  dataAccessLedgerAccounts?: Maybe<DataAccess_LedgerAccountConnection>;
  /** All the Milestone entities associated with the company */
  dataAccessMilestones?: Maybe<DataAccess_MilestoneConnection>;
  /** All the Work Project entities associated with the company */
  dataAccessNavigations?: Maybe<DataAccess_NavigationConnection>;
  /** All the banking transactions associated with the company. */
  dataAccessOFXTransactions?: Maybe<DataAccess_OfxTransactionConnection>;
  /** All payment methods associated with a company. */
  dataAccessPaymentMethods?: Maybe<DataAccess_PaymentMethodConnection>;
  dataAccessProducts?: Maybe<DataAccess_ProductConnection>;
  /** All the RecurringProject entities associated with the company */
  dataAccessRecurringProjects?: Maybe<DataAccess_RecurringProjectConnection>;
  /** All the SharedLedgerAccount entities associated with the company */
