  /** Get a list of tax classifications */
  dataAccessTaxClassifications?: Maybe<DataAccess_TaxClassificationConnection>;
  /** All the TaxGroup entities associated with the company */
  dataAccessTaxGroups?: Maybe<DataAccess_TaxGroupConnection>;
  /** All the TaxRate entities associated with the company */
  dataAccessTaxRates?: Maybe<DataAccess_TaxRateConnection>;
  /** All the Term entities associated with the company */
  dataAccessTerms?: Maybe<DataAccess_TermConnection>;
  /** Transaction lines from the QBO Monolith line-search API. */
