/**
 * Represents a worker in the system.
 * This type provides comprehensive information about the worker including personal details,
 * employment status, contact information, and access to sensitive data.
 */
export type WorkerManagement_Worker = {
  __typename?: 'WorkerManagement_Worker';
  /**
   * Alternate identifiers for the worker in different systems or namespaces.
   * Can be filtered by namespace to retrieve specific alternate IDs.
   * Useful for cross-system integration and mapping.
   */
  alternateIds: Array<Qb_AlternateId>;
  /**
   * Contact information of the worker.
   * Includes phone numbers, email addresses, and physical addresses (home and mailing).
   * This information is used for communication and payroll-related correspondence.
   */
  contactInfo?: Maybe<WorkerManagement_WorkerContactInfo>;
  /**
   * Name for display purposes.
   * This is typically a formatted combination of first, middle, and last names,
   * or a preferred name chosen by the worker for UI display.
   */
  displayName?: Maybe<Scalars['String']['output']>;
  /**
   * Emergency contacts for the worker.
   * A list of people to contact in case of an emergency involving the worker.
   * Each contact includes name, relationship, phone number, and optionally email address.
   */
  emergencyContacts: Array<WorkerManagement_EmergencyContact>;
  /**
   * Employment details for the worker.
   * Contains information about the worker's most recent employment regardless of current status.
   * Includes hire date, termination date (if applicable), job title, worker identifier,
   * job costing information, and status change reasons.
   */
  employmentDetail?: Maybe<WorkerManagement_EmploymentDetail>;
  /**
   * Employment eligibility information for the worker.
   * Represents verification data related to the worker's legal authorization to work.
   * Can be filtered using the input parameter to retrieve specific verification types.
   */
  employmentEligibility?: Maybe<WorkerManagement_EmploymentEligibility>;
  /**
   * Employment status of the worker.
   * Indicates whether the worker is active or inactive for payroll purposes,
   * along with detailed status information such as ACTIVE, TERMINATED, PAID_LEAVE, etc.
   */
  employmentStatus?: Maybe<WorkerManagement_EmploymentStatus>;
  /**
   * First name of the worker.
   * This is a required field for all workers.
   */
  firstName: Scalars['String']['output'];
  /**
   * Gender of the worker.
   * Each tax jurisdiction supports different set of genders.
   * Common values include: MALE, FEMALE, OTHER, UNKNOWN.
   * The specific values available may vary based on the worker's location and applicable tax laws.
   */
  gender?: Maybe<Scalars['String']['output']>;
  /**
   * Indicates whether the worker is hidden from active lists and standard views.
   * Hidden workers are typically those who are no longer active but whose records
   * need to be retained for historical or compliance purposes.
   * - true = worker is hidden from standard views
   * - false/null = worker is visible in standard views
   */
  hidden?: Maybe<Scalars['Boolean']['output']>;
  /**
   * Unique identifier for the worker.
   * This ID is used as the primary key for federation and all worker-related operations.
   */
  id: Scalars['ID']['output'];
  /**
   * Last name of the worker.
   * This is a required field for all workers.
   */
  lastName: Scalars['String']['output'];
  /**
   * Limited access fields containing sensitive and personally identifiable information (PII).
   * Includes tax identifiers (SSN, SIN, etc.) and birth date.
   * By default, values are sensitized (partially obfuscated) to protect privacy.
   * Full plain text values can be requested through arguments, but require elevated privileges.
   * Users with low access permissions will only receive sensitized content even if they request non-sensitized data.
   */
  limitedAccessFields?: Maybe<WorkerManagement_WorkerLimitedAccessFields>;
  /**
   * Manager of the worker.
   * References another employee who serves as this worker's direct supervisor or manager.
   * May be null if the worker has no assigned manager or is a top-level employee.
   */
  manager?: Maybe<WorkerManagement_Worker>;
  /**
   * Metadata about the worker record.
   * Contains information about when the record was created, last updated,
   * and other audit trail information related to the payroll employer data.
   */
  metadata?: Maybe<Qb_Metadata>;
  /**
   * Middle name of the worker.
   * This field is optional and may be null if the worker has no middle name.
   */
  middleName?: Maybe<Scalars['String']['output']>;
  /**
   * Name to be printed on the worker's paycheck.
   * This may differ from the legal name and allows for preferred names or nicknames.
   * If not specified, defaults to the worker's legal name.
   */
  printOnCheckName?: Maybe<Scalars['String']['output']>;
  /**
   * Profile picture documents for the worker.
   * Returns a list of picture objects that can be used to display the worker's photo in the UI.
   * May be empty if no profile pictures have been uploaded.
   */
  profilePictures?: Maybe<Array<WorkerManagement_Picture>>;
  /**
   * Name suffix of the worker.
   * Examples include Jr., Sr., III, PhD, etc.
   * This field is optional and may be null.
   */
  suffix?: Maybe<Scalars['String']['output']>;
  /**
   * Professional or courtesy title of the worker.
   * Examples include Mr., Mrs., Ms., Dr., etc.
   * This field is optional and may be null.
   */
  title?: Maybe<Scalars['String']['output']>;
  /** entity version */
  version?: Maybe<Scalars['String']['output']>;
  /**
   * Access and identity information for this worker.
   * Contains the digital identity and profile associations created through the worker portal invitation flow.
   */
  workerAccess?: Maybe<WorkerManagement_WorkerAccess>;
  /**
   * Type of worker.
   * Determines the worker's classification in the system.
   */
  workerType?: Maybe<WorkerManagement_WorkerTypeEnum>;
};


